    async def update(
        self,
        id: str,
        *,
        configuration: typing.Dict[str, typing.Any],
        name: str,
        healthcheck_interval: typing.Optional[str] = OMIT,
        organization_id: typing.Optional[str] = OMIT,
        policies: typing.Optional[typing.Sequence[str]] = OMIT,
        reconnect: typing.Optional[bool] = OMIT,
        type: typing.Optional[str] = OMIT,
        validate: typing.Optional[bool] = OMIT,
        idempotency_key: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CreateConnectionResponseEnvelope:
        """
        Updates a connection's configuration.

        Connections owned by a managed Harbor return `409 Conflict`. To rename the
        Connection, [update its Harbor](../../../api-reference/harbors/update). Customer-managed
        Harbor backing Connections remain independently editable.

        Updating a connection is a **full replacement** of its configuration. Any
        `configuration` field you omit is cleared. To make a partial change, fetch
        the current connection with
        [`GET /api/connections/{id}`](../../../api-reference/connections/get), apply your edits, and send the
        complete object back.

        > 📘 The connection is re-validated against the upstream service after every
        > update. The request will fail if the new credentials or endpoint cannot be
        > reached.

        Syncs that are already running when the update is submitted are not
        interrupted; the updated configuration takes effect on their next execution.

        Parameters
        ----------
        id : str

        configuration : typing.Dict[str, typing.Any]

        name : str

        healthcheck_interval : typing.Optional[str]
            Override interval for connection health checking.

        organization_id : typing.Optional[str]

        policies : typing.Optional[typing.Sequence[str]]

        reconnect : typing.Optional[bool]

        type : typing.Optional[str]

        validate : typing.Optional[bool]
            Validate connection configuration.

        idempotency_key : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CreateConnectionResponseEnvelope
            OK

        Examples
        --------
        import asyncio

        from polytomic import AsyncPolytomic

        client = AsyncPolytomic(
            "2025-09-18",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.connections.update(
                id="248df4b7-aa70-47b8-a036-33ac447e668d",
                configuration={
                    "database": "example",
                    "hostname": "postgres.example.com",
                    "password": "********",
                    "port": 5432,
                    "username": "user",
                },
                name="My Postgres Connection",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update(
            id,
            configuration=configuration,
            name=name,
            healthcheck_interval=healthcheck_interval,
            organization_id=organization_id,
            policies=policies,
            reconnect=reconnect,
            type=type,
            validate=validate,
            idempotency_key=idempotency_key,
            request_options=request_options,
        )
        return _response.data

    async def delete(
        self,
        id: str,
        *,
        force: typing.Optional[bool] = None,
        idempotency_key: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> None:
        """
        Deletes a connection.

        A Connection that backs any active Harbor returns `409 Conflict`, including
        when you pass `force=true`. No dependent resources are deleted in this case.
        [Delete the Harbor](../../../api-reference/harbors/delete) first. Deleting a managed
        Harbor also deletes its managed Connection; deleting a customer-managed Harbor
        preserves its backing Connection.

        > 🚧 Deleting a connection that is referenced by fieldsets, syncs, bulk
        > syncs, or schedules returns `422 connection in use` unless you pass
        > `force=true`. With `force=true`, the API deletes those dependent
        > resources before removing the connection.

        Parameters
        ----------
        id : str

        force : typing.Optional[bool]

        idempotency_key : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        None

        Examples
        --------
        import asyncio

        from polytomic import AsyncPolytomic

        client = AsyncPolytomic(
            "2025-09-18",
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.connections.delete(
                id="248df4b7-aa70-47b8-a036-33ac447e668d",
                force=True,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.delete(
            id, force=force, idempotency_key=idempotency_key, request_options=request_options
        )
        return _response.data

